import {getCases,getFreeCase,words} from './content.js';
import {initLearningMap} from './learning-map.js';
import {textFields,localDate,validDate,validateSession,sanitizeSession,summarizeSessions,mergeBackup,escapeHtml} from './reports.js';

const KEY='learning-together-v2',DRAFT_KEY='learning-together-drafts-v2',$=s=>document.querySelector(s),esc=escapeHtml;
let state={lang:'en',name:'',age:8,remember:false,sessions:[],drafts:{},legacy:{}},storageOK=true;
try{const old=JSON.parse(localStorage.getItem('family-lab-v1')||'null');if(old){state.age=[6,7,8,9,10,11].includes(old.age)?old.age:8;state.legacy=old.records||{};}const raw=JSON.parse(localStorage.getItem(KEY)||'null');if(raw?.remember===true){state={...state,lang:raw.lang==='zh'?'zh':'en',name:typeof raw.name==='string'?raw.name.slice(0,60):'',age:[6,7,8,9,10,11].includes(raw.age)?raw.age:8,remember:true,sessions:(Array.isArray(raw.sessions)?raw.sessions:[]).map(s=>sanitizeSession(s,[...getCases('en'),getFreeCase('en')])).filter(Boolean),legacy:raw.legacy||state.legacy};}const d=JSON.parse(localStorage.getItem(DRAFT_KEY)||'null');if(d&&typeof d==='object')state.drafts=d;}catch{storageOK=false;}
let page='cases',selected='little-teacher',currentReport=null,toastTimer;
const W=()=>words[state.lang],L=(en,zh)=>state.lang==='en'?en:zh,C=()=>[...getCases(state.lang),getFreeCase(state.lang)],active=()=>C().find(c=>c.id===selected)||C()[0];
const uuid=()=>globalThis.crypto?.randomUUID?.()||`session-${Date.now()}-${Math.random().toString(36).slice(2)}`;
function toast(message){$('#notice').textContent=message;$('#notice').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#notice').hidden=true,4500);}
function persist(){try{localStorage.setItem(DRAFT_KEY,JSON.stringify(state.drafts));if(state.remember)localStorage.setItem(KEY,JSON.stringify({...state,drafts:undefined}));storageOK=true;}catch{storageOK=false;}const el=$('#saveState');if(el)el.textContent=storageOK?(state.remember?W().saved:L('Export to keep your records','导出文件以长期保留记录')):W().offlineError;return storageOK;}
function ensureDraft(){const raw=state.drafts[selected]||{};const str=v=>typeof v==='string'?v.slice(0,3000):'';const d={id:typeof raw.id==='string'&&raw.id.length>0&&raw.id.length<=120?raw.id:uuid(),caseId:selected,date:typeof raw.date==='string'?raw.date:localDate(),age:state.age,custom:{title:str(raw.custom?.title).slice(0,160),materials:str(raw.custom?.materials),plan:str(raw.custom?.plan)},fields:Object.fromEntries(textFields.map(k=>[k,str(raw.fields?.[k])])),rows:Array.from({length:3},(_,i)=>({rating:['unknown','supported','independent'].includes(raw.rows?.[i]?.rating)?raw.rows[i].rating:'unknown',evidence:str(raw.rows?.[i]?.evidence)})),createdAt:typeof raw.createdAt==='string'?raw.createdAt:new Date().toISOString(),updatedAt:typeof raw.updatedAt==='string'?raw.updatedAt:''};state.drafts[selected]=d;return d;}
function saveForm(){const form=$('#practiceForm');if(!form)return;const d=ensureDraft();d.date=form.elements.practiceDate.value;d.age=state.age;if(active().custom)d.custom={title:form.elements.activityTitle.value,materials:form.elements.activityMaterials.value,plan:form.elements.activityPlan.value};for(const key of textFields)d.fields[key]=form.elements[key].value;d.rows=d.rows.map((r,i)=>({rating:form.elements['rating'+i].value,evidence:form.elements['evidence'+i].value}));d.updatedAt=new Date().toISOString();persist();const label=$('#draftStatus');if(label)label.textContent=storageOK?W().draft:W().offlineError;}
function go(next){saveForm();if(next==='workbook'){selected='open-exploration';currentReport=null;}if(next==='cases'&&active().custom)selected='little-teacher';page=next==='portrait'?'workbook':next;render();if(next==='portrait'){const reports=$('#savedReports');reports.open=true;reports.scrollIntoView({block:'start'});}else window.scrollTo({top:0,behavior:'auto'});}
function setCase(id,start=false){saveForm();if(!C().some(c=>c.id===id))throw new Error('Unknown case');selected=id;currentReport=null;if(start||active().custom)page='workbook';render();}
function render(){document.documentElement.lang=state.lang==='en'?'en':'zh-CN';document.title=L('Second Path · Learning to Learn','第二路径 · 学会学习');$('#brandName').textContent=L('Second Path','第二路径');$('.brand').setAttribute('aria-label',L('Second Path — explore another way to learn','第二路径：探索另一种学法'));const w=W();$('#language').value=state.lang;$('.breadcrumbs').textContent=L('LEARNING TO LEARN / FAMILY STUDIO','学会学习 / 家庭练习室');$('#sideNav').setAttribute('aria-label',L('Main sections','主要栏目'));
$('#sideNav').innerHTML=['cases','workbook'].map(key=>`<button class="nav-item ${page===key?'active':''}" data-page="${key}" aria-current="${page===key?'page':'false'}"><span><strong>${w[key]}</strong><small>${w[key==='cases'?'caseHint':'workbookHint']}</small></span></button>`).join('');
$('#learnerControls').innerHTML=`<label>${w.nickname}<input id="learnerName" maxlength="60" value="${esc(state.name)}" placeholder="${L('My learner','我的学习者')}"></label><label>${w.age}<select id="learnerAge">${[6,7,8,9,10,11].map(n=>`<option ${n===state.age?'selected':''} value="${n}">${n}</option>`).join('')}</select></label><label class="remember-choice"><input id="remember" type="checkbox" ${state.remember?'checked':''}><span>${L('Keep records on this device','在此设备保留记录')}</span></label><p class="side-note">${state.remember?w.storage:L('Until enabled, saved sessions stay in this open page. Export a backup before leaving. Form drafts are cached locally.','开启前，已生成的报告只在本次打开的页面里保留。离开前请导出备份；填写草稿会缓存在本机。')}</p>`;
$('#sectionLabel').textContent=L('LEARNING TO LEARN','学会学习');$('#pageTitle').textContent=w[page];$('#pageIntro').textContent=page==='cases'?L('Choose any of the 22 cases. Use the same observation template each time.','任选一个案例，用同一份模板记录每次尝试。'):L('An idea, a game, an experiment — start with what your child wants to try.','一个点子、一个游戏、一个小实验，从孩子想玩的事情开始。');
$('#sessionCount').textContent=state.sessions.length;$('#sessionCountLabel').textContent=w.savedSessions;
$('#footer').innerHTML=`<div class="feedback-row"><div><h2>${L('Have an idea for Second Path?','对第二路径有什么想法？')}</h2><p>${L('Suggest an improvement, report a problem, or share a new activity.','提个建议、反馈问题，或分享一个新的活动点子。')}</p><p class="feedback-note">${L('GitHub sign-in required. Feedback is public; please leave out children’s private information.','需要登录 GitHub。留言公开可见，请勿填写孩子的隐私信息。')}</p></div><a class="feedback-link" href="https://github.com/hedybi/second-path-for-kids/issues/new" target="_blank" rel="noopener noreferrer">${L('Share feedback','建议与反馈')} ↗</a></div><div class="footer-credits"><div>${w.source} <a href="https://github.com/withmarbleapp/os-taxonomy" target="_blank" rel="noopener">Marble Skill Taxonomy · GitHub ↗</a><br><span>© Generative Spark, Inc. (Marble) · <a href="https://opendatacommons.org/licenses/odbl/1-0/">ODbL 1.0</a> / <a href="https://creativecommons.org/licenses/by-sa/4.0/">CC BY-SA 4.0</a> · <button class="text-button" id="showCredits">${L('Sources & adaptations','来源与改编说明')}</button></span></div><p>${w.design}</p></div>`;
$('#mainView').innerHTML=page==='cases'?renderCases():renderWorkbook();
document.querySelectorAll('#sideNav [data-page]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.page)));
$('#learnerName').addEventListener('input',e=>{state.name=e.target.value;persist();});$('#learnerAge').addEventListener('change',e=>{saveForm();state.age=Number(e.target.value);persist();render();});$('#remember').addEventListener('change',e=>{saveForm();state.remember=e.target.checked;if(!state.remember)try{localStorage.removeItem(KEY);}catch{}persist();render();});
$('#showCredits').addEventListener('click',showCredits);bindView();persist();}
function renderCases(){const w=W(),c=active(),list=getCases(state.lang);return `<section class="case-workspace"><div class="case-selector"><button class="free-template-card" data-free-template><span>↗</span><strong>${L("Your own idea","孩子自己的点子")}</strong><small>${L("Open a blank template","打开万能模板，自由填写")}</small></button><div class="case-list-heading"><span>${L('All cases','全部案例')}</span><span class="case-total">${list.length}</span></div><div class="case-list">${list.map((a,i)=>`<button data-case="${a.id}" class="case-option ${a.id===c.id?'chosen':''}" aria-pressed="${a.id===c.id}"><span>${String(i+1).padStart(2,'0')}</span><div><strong>${esc(a.title)}</strong><small>${esc(a.skillName)}</small></div></button>`).join('')}</div></div><article class="case-detail"><div class="card-top"><span class="tag">${esc(c.skillName)}</span><span class="muted">${w.minutes}</span></div><h2>${esc(c.title)}</h2><p class="lead">${esc(c.summary)}</p><div class="materials"><span>${w.materials}</span><p>${esc(c.materials)}</p></div><h3>${w.steps}</h3><ol class="steps-list">${c.steps.map((s,i)=>`<li><span class="step-dot">0${i+1}</span><div><h4>${esc(s[0])}</h4><p>${esc(s[1])}</p></div></li>`).join('')}</ol><div class="prompt-box"><span>${w.ask}</span><p>“${esc(c.question)}”</p></div><details class="observations-preview"><summary>${w.observe}</summary><ul>${c.observations.map(o=>`<li>${esc(o)}</li>`).join('')}</ul></details><p class="help-text">${esc(c.prep)} ${L('Reference age','原始参考年龄')}: ${c.skillAge.join('–')}.</p><div class="case-actions"><button class="primary" id="startPractice">${w.start} <span>↗</span></button><a class="source-link" href="https://github.com/withmarbleapp/os-taxonomy/blob/main/data/topics.json#L${c.sourceLine}" target="_blank" rel="noopener">${w.viewSource} ↗</a></div><p class="fine">${w.adapted}</p></article></section><details class="map-disclosure"><summary><span>${w.map}</span><small>${w.mapHint}</small></summary><section id="learningMap" class="learning-map"></section></details>`;}
function renderWorkbook(){const w=W(),c=active(),d=ensureDraft();return `<div class="workbook-heading"><p class="muted">${L('Case','当前案例')} · <strong>${esc(c.title)}</strong></p><button class="secondary" data-page="cases">${L('Choose another case','更换案例')}</button></div><form id="practiceForm" novalidate><div class="form-top"><div><p class="eyebrow">${esc(c.skillName)}</p><h2>${esc(c.title)}</h2></div><label>${w.date}<input name="practiceDate" type="date" max="${localDate()}" value="${esc(d.date)}" required></label></div>${c.custom?`<div class="custom-idea-fields"><label class="field">${L('Give your activity a name','给这次活动起个名字')}<input name="activityTitle" maxlength="160" value="${esc(d.custom.title)}" placeholder="${L('For example: a secret city for our toys','例如：给玩具建一座秘密城市')}" required></label><label class="field">${L('What will you use?','准备用什么材料？')}<textarea name="activityMaterials" maxlength="3000">${esc(d.custom.materials)}</textarea></label><label class="field">${L('How does your child want to play or try it?','孩子打算怎么玩、怎么做？')}<textarea name="activityPlan" maxlength="3000" placeholder="${L('Write the plan in their own words. It can change as you go.','记下孩子自己的玩法，过程中随时可以改变。')}">${esc(d.custom.plan)}</textarea></label></div><p class="help-text">${L('No Marble skill needs to be chosen. Record the experience in your own words; the behavior checklist is optional.','不需要先选能力分类。用自己的话记录过程；下面的行为观察可以选填。')}</p>`:''}<div class="form-grid">${['goal','prediction'].map(k=>field(k,d)).join('')}</div>${c.custom?'':`<details class="inline-instructions"><summary>${w.steps}</summary><ol>${c.steps.map(s=>`<li><strong>${esc(s[0])}</strong> — ${esc(s[1])}</li>`).join('')}</ol></details>`}<div class="form-grid">${['attempt','change'].map(k=>field(k,d)).join('')}</div><h3>${L('Observe while you practise','边做边观察')}</h3><p class="help-text">${L('“Not observed” means we do not have evidence yet. Choose a level only when you can add an example.','“暂未观察到”表示还没有证据。有具体例子时，再选择相应表现。')}</p><div class="table-scroll"><table class="observation-table"><thead><tr><th>${w.behavior}</th><th>${w.level}</th><th>${w.evidence}</th></tr></thead><tbody>${c.observations.map((o,i)=>`<tr><td><span class="row-index">0${i+1}</span>${esc(o)}</td><td><fieldset class="rating-choices"><legend class="sr-only">${esc(o)} — ${w.level}</legend>${['unknown','supported','independent'].map(r=>`<label><input type="radio" name="rating${i}" value="${r}" ${d.rows[i].rating===r?'checked':''}><span>${w[r]}</span></label>`).join('')}</fieldset></td><td><textarea name="evidence${i}" maxlength="3000" aria-label="${esc(o)} — ${w.evidence}" placeholder="${L('What did they say or do?','孩子具体说了什么、做了什么？')}">${esc(d.rows[i].evidence)}</textarea></td></tr>`).join('')}</tbody></table></div><div class="form-grid">${['support','childVoice','adultReflection','next'].map(k=>field(k,d)).join('')}</div><p id="formError" class="error" role="alert" hidden></p><div class="form-actions"><button class="primary" type="submit">${w.generate} ↗</button><button class="secondary" type="button" id="freshSession">${w.newSession}</button><span class="fine" id="draftStatus">${L('Your draft is saved on this device','草稿缓存在此设备')}</span></div></form><section id="sessionReport">${currentReport?reportContent(state.sessions.find(s=>s.id===currentReport)):''}</section><details id="savedReports" class="saved-reports"><summary>${L('Reports & saved records','报告与已有记录')} <span class="case-total">${state.sessions.length}</span></summary><div class="saved-reports-body">${renderPortrait()}</div></details>`;}
function field(key,d){return `<label class="field">${W()[key]}<textarea name="${key}" maxlength="3000" rows="2">${esc(d.fields?.[key]||'')}</textarea></label>`;}
function sessionTitle(s){const c=C().find(a=>a.id===s.caseId);return c?.custom?s.custom?.title||c.title:c?.title||'';}
function reportContent(s){if(!s)return '';const w=W(),c=C().find(a=>a.id===s.caseId),stats=summarizeSessions([s],C());return `<article class="report-card" data-report="${esc(s.id)}"><div class="report-top"><div><p class="eyebrow">${w.report}</p><h2>${esc(sessionTitle(s))}</h2><p class="muted">${esc(state.name||L('My learner','我的学习者'))} · ${esc(s.date)} · ${s.age} ${L('years','岁')}</p></div><span class="report-badge">${w.note}</span></div><div class="report-counts"><div><strong>${stats.independent}</strong><span>${w.indCount}</span></div><div><strong>${stats.supported}</strong><span>${w.supCount}</span></div><div><strong>${stats.unknown}</strong><span>${w.notCount}</span></div></div><h3>${w.insights}</h3>${stats.observed?`<p>${L('In this activity, the notes contain','这次活动中，记录了')} ${stats.independent} ${L('independent and','条独立完成的例子，以及')} ${stats.supported} ${L('supported examples. These describe this attempt, not a fixed ability.','条借助提示的例子。它们描述本次尝试，不代表固定能力。')}</p>`:`<p>${w.emptySummary}</p>`}<ul class="evidence-list">${s.rows.map((r,i)=>`<li><div><strong>${esc(c.observations[i])}</strong><span class="rating ${r.rating}">${w[r.rating]}</span></div>${r.evidence?`<blockquote>${esc(r.evidence)}</blockquote>`:`<p class="fine">${w.notCount}</p>`}</li>`).join('')}</ul><div class="report-fields">${c.custom?`<div><h4>${L("Materials","材料")}</h4><p>${esc(s.custom?.materials)}</p></div><div><h4>${L("The learner’s plan","孩子自己的玩法")}</h4><p>${esc(s.custom?.plan)}</p></div>`:''}${textFields.filter(k=>s.fields[k]).map(k=>`<div><h4>${w[k]}</h4><p>${esc(s.fields[k])}</p></div>`).join('')}</div><div class="recommendation"><h3>${w.nextSteps}</h3><p>${s.fields.next?esc(s.fields.next):stats.supported?L('Try one of the supported steps again, keeping the helpful prompt. On another day, see whether less help is enough.','再试一个需要提示的步骤，先保留有效帮助。换一天观察是否可以减少提示。'):L('Try a similar task on another day. Record whether the same behavior appears in a new example.','换一天做一个相似任务，观察同样的行为是否在新例子中出现。')}</p></div><p class="report-method">${w.method}</p><div class="report-actions"><button class="primary" data-export-session="${esc(s.id)}">${w.exportReport} ↓</button><button class="secondary" data-print-session="${esc(s.id)}">${w.print}</button><button class="text-button" data-page="portrait">${w.portrait} →</button></div></article>`;}
function renderPortrait(){const w=W(),stats=summarizeSessions(state.sessions,C());let body=`<div class="portrait-top"><div><p class="eyebrow">${w.note}</p><h2>${esc(state.name||L('My learner','我的学习者'))}</h2><p class="muted">${w.scope}</p></div><div class="backup-actions"><button class="secondary" id="backup">${w.download} ↓</button><label class="secondary import-label">${w.restore}<input type="file" id="restoreFile" accept="application/json,.json" hidden></label></div></div><div class="metric-grid"><div><span>${w.sessions}</span><strong>${stats.sessions.toString().padStart(2,'0')}</strong></div><div><span>${w.skills}</span><strong>${stats.skills.toString().padStart(2,'0')}</strong></div><div><span>${w.observations}</span><strong>${stats.observed.toString().padStart(2,'0')}</strong></div></div>`;
if(!stats.sessions)body+=`<div class="empty-state"><span>↗</span><h3>${w.noData}</h3><p>${w.noDataHint}</p><button class="primary" data-page="workbook">${w.openWorkbook}</button></div>`;
else{const strong=stats.bySkill.filter(s=>!s.custom&&s.independent>0),help=stats.bySkill.filter(s=>!s.custom&&s.supported>0);body+=`<div id="portraitReport"><div class="insight-grid"><section class="insight-card"><span class="eyebrow">01 / ${w.insights}</span>${strong.length?strong.map(s=>`<h3>${esc(s.name)}</h3><p>${L('Recorded','记录到')} ${s.independent} ${L('independent examples across','条独立完成例子，来自')} ${s.sessions} ${L('sessions.','次练习。')}</p><small>${s.independentSessions>=3&&s.independentDates.length>=2?w.repeat:w.few}</small>`).join(''):`<p>${L('No independent examples have been recorded for the mapped skills yet. Child-led activities appear in their own reports.','现有能力分类下还没有独立完成的记录。自主活动的表现保留在各自报告里。')}</p>`}</section><section class="insight-card"><span class="eyebrow">02 / ${w.supports}</span>${help.length?help.map(s=>`<h3>${esc(s.name)}</h3><p>${s.supported} ${L('examples were recorded with support.','条记录是在提示或帮助下完成的。')}</p>`).join(''):`<p>${L('No supported attempts were recorded. This does not mean support is unnecessary.','目前没有提示后完成的记录，不代表不需要帮助。')}</p>`}${state.sessions.filter(s=>s.fields.support).slice(-3).map(s=>`<blockquote>${esc(s.fields.support)}<cite>${esc(s.date)}</cite></blockquote>`).join('')}</section></div><section class="coverage-card"><h3>${w.coverage}</h3>${stats.bySkill.some(s=>s.custom)?`<p class="fine">${L("Child-led activities are listed separately and are not assigned to Marble skills.","自主活动单独列出，不自动归入 Marble 能力。")}</p>`:''}<div class="table-scroll"><table><thead><tr><th>${w.skills}</th><th>${w.sessions}</th><th>${w.indCount}</th><th>${w.supCount}</th><th>${w.notCount}</th></tr></thead><tbody>${stats.bySkill.map(s=>`<tr><td>${esc(s.name)}</td><td>${s.sessions}</td><td>${s.independent}</td><td>${s.supported}</td><td>${s.unknown}</td></tr>`).join('')}</tbody></table></div></section><div class="recommendation"><h3>${w.nextSteps}</h3><p>${!stats.skills?L('Revisit one of your own activities. Ask what your child wants to keep, change or try next.','选一个你们自己的活动，问问孩子想保留什么、改变什么、下一次试什么。'):help.length?L('Revisit one supported step and note the help that makes it possible. Compare another attempt on a different day.','重访一个需要支持的步骤，记下哪种帮助让它变得可行，再换一天比较。'):L('Choose a different context for one observed skill. Look for what carries over and what needs new support.','为已观察的一项能力换个情境，看看哪些表现能够迁移、哪些需要新的帮助。')}</p><ul>${state.sessions.filter(s=>s.fields.next).slice(-3).map(s=>`<li>${esc(s.fields.next)} <span class="fine">${esc(s.date)}</span></li>`).join('')}</ul></div><p class="report-method">${w.method}</p></div><div class="report-actions"><button class="primary" id="exportPortrait">${w.exportReport} ↓</button><button class="secondary" id="printPortrait">${w.print}</button></div><section class="history"><h3>${w.history}</h3>${[...state.sessions].sort((a,b)=>b.date.localeCompare(a.date)).map(s=>`<button data-review="${esc(s.id)}"><span>${esc(s.date)}</span><strong>${esc(sessionTitle(s))}</strong><span>${w.review} ↗</span></button>`).join('')}</section>`;}
const legacy=Object.entries(state.legacy||{}).filter(([id,r])=>r&&(r.done||r.note||(Array.isArray(r.checks)&&r.checks.some(Boolean))));if(legacy.length)body+=`<details class="legacy"><summary>${w.legacy} · ${legacy.length}</summary><p>${L('Earlier notes are preserved below. They are not counted as structured sessions because the original checkboxes did not record independence or support.','旧笔记保留在下面。原来的勾选没有区分独立或提示完成，因此不计入新的结构化报告。')}</p>${legacy.map(([id,r])=>`<div><h4>${esc(C().find(c=>c.id===id)?.title||id)}</h4><p>${esc(r.note||'')}</p></div>`).join('')}</details>`;return body;}
function bindView(){$('[data-free-template]')?.addEventListener('click',()=>setCase('open-exploration',true));document.querySelectorAll('#mainView [data-page]').forEach(b=>b.addEventListener('click',()=>go(b.dataset.page)));document.querySelectorAll('[data-case]').forEach(b=>b.addEventListener('click',()=>setCase(b.dataset.case)));$('#startPractice')?.addEventListener('click',()=>setCase(selected,true));
$('#practiceForm')?.addEventListener('input',saveForm);$('#practiceForm')?.addEventListener('change',saveForm);$('#practiceForm')?.addEventListener('submit',e=>{e.preventDefault();saveForm();const d=ensureDraft(),error=$('#formError');if(!validDate(d.date)||!validateSession(d,C())){error.textContent=!validDate(d.date)?W().dateError:active().custom?L('Add an activity name and describe what happened, or record a behavior with an example. Every rated behavior needs evidence.','请填写活动名称和实际尝试过程，或记录一项行为及具体例子；已选表现的行为都需要例子。'):W().required;error.hidden=false;error.scrollIntoView({block:'center'});return;}const s=sanitizeSession(d,C()),i=state.sessions.findIndex(x=>x.id===s.id);if(i<0)state.sessions.push(s);else state.sessions[i]=s;currentReport=s.id;persist();render();$('#sessionReport').scrollIntoView({block:'start'});toast(state.remember?W().savedReport:L('Report generated. Export a backup to keep it.','报告已生成，请导出备份以保留记录。'));});
$('#freshSession')?.addEventListener('click',()=>{saveForm();const d=ensureDraft();const saved=state.sessions.find(s=>s.id===d.id),hasContent=(active().custom&&(d.custom.title||d.custom.materials||d.custom.plan))||d.rows.some(r=>r.rating!=='unknown'||r.evidence)||textFields.some(k=>d.fields[k]),changed=saved&&(saved.date!==d.date||saved.age!==d.age||JSON.stringify(saved.rows)!==JSON.stringify(d.rows)||(active().custom&&JSON.stringify(saved.custom)!==JSON.stringify(d.custom))||textFields.some(k=>saved.fields[k]!==d.fields[k]));if(changed||(!saved&&hasContent)){toast(L('Save the current report before starting a fresh session. Your draft has been kept.','请先保存当前报告，再开始新记录。草稿已保留。'));return;}delete state.drafts[selected];currentReport=null;persist();render();});
document.querySelectorAll('[data-review]').forEach(b=>b.addEventListener('click',()=>{saveForm();const s=state.sessions.find(s=>s.id===b.dataset.review);selected=s.caseId;currentReport=s.id;page='workbook';render();$('#sessionReport').scrollIntoView({block:'start'});}));document.querySelectorAll('[data-export-session]').forEach(b=>b.addEventListener('click',()=>exportSession(b.dataset.exportSession,false)));document.querySelectorAll('[data-print-session]').forEach(b=>b.addEventListener('click',()=>exportSession(b.dataset.printSession,true)));$('#exportPortrait')?.addEventListener('click',()=>exportPortrait(false));$('#printPortrait')?.addEventListener('click',()=>exportPortrait(true));$('#backup')?.addEventListener('click',exportBackup);$('#restoreFile')?.addEventListener('change',restoreBackup);
if($('#learningMap'))initLearningMap({lang:state.lang,openActivity:id=>setCase(id,true),caseForSkill:skillId=>C().find(c=>c.skillId===skillId)?.id});}
function download(text,name,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function reportDocument(title,body){return `<!doctype html><html lang="${state.lang}"><meta charset="utf-8"><title>${esc(title)}</title><style>body{font:16px/1.7 system-ui,sans-serif;color:#17261e;max-width:900px;padding:38px;margin:auto}h1,h2,h3{line-height:1.35}h2{font-size:26px}h3{margin-top:28px}table{border-collapse:collapse;width:100%}td,th{border-bottom:1px solid #ccc;text-align:left;padding:10px}blockquote{border-left:3px solid #41834f;padding:9px 15px;margin:12px 0;white-space:pre-wrap;background:#f2f7f1}cite{display:block;font-size:12px}p{white-space:pre-wrap}button,.report-actions{display:none}.report-counts,.metric-grid{display:flex;gap:40px}.report-counts strong{font-size:28px;display:block}.report-counts span{display:block;font-size:13px}.rating{margin-left:15px;font-size:13px}.report-method,.fine{color:#586259;font-size:13px}.report-fields{display:grid;grid-template-columns:1fr 1fr;gap:18px}.report-fields h4{margin-bottom:3px}.evidence-list{list-style:none;padding:0}.evidence-list li{margin:18px 0}.recommendation{padding:15px;background:#f2f7f1}a{color:#236330}@media print{body{padding:0}tr,blockquote,.report-fields>div{break-inside:avoid}h2,h3,h4{break-after:avoid}}</style><body><h1>${esc(title)}</h1>${body}<hr><p>${W().design}<br>${W().source} <a href="https://github.com/withmarbleapp/os-taxonomy">Marble Skill Taxonomy</a> · © Generative Spark, Inc. (Marble) · ODbL 1.0 / CC BY-SA 4.0.</p></body></html>`;}
function deliverReport(title,body,print){const html=reportDocument(title,body);if(!print){download(html,'learning-report-'+localDate()+'.html','text/html;charset=utf-8');return;}const frame=document.createElement('iframe');frame.setAttribute('title',L('Print report','打印报告'));frame.style.cssText='position:fixed;right:0;bottom:0;width:1px;height:1px;border:0';frame.onload=()=>{try{frame.contentWindow.focus();frame.contentWindow.print();}catch{toast(L('Download the report and print it in your browser.','请下载报告，再用浏览器打印。'));}setTimeout(()=>frame.remove(),60000);};frame.srcdoc=html;document.body.append(frame);}
function exportSession(id,print){const s=state.sessions.find(s=>s.id===id);if(s)deliverReport(W().report,reportContent(s),print);}
function exportPortrait(print){const html=$('#portraitReport')?.innerHTML;if(html)deliverReport(`${W().portrait} — ${state.name||L('My learner','我的学习者')}`,`<p>${esc(state.name)} · ${state.sessions.length} ${W().sessions} · ${W().scope}</p>${html}`,print);}
function exportBackup(){saveForm();download(JSON.stringify({format:'learning-together-v2',exportedAt:new Date().toISOString(),learner:{name:state.name,age:state.age},sessions:state.sessions,legacy:state.legacy},null,2),'learning-backup-'+localDate()+'.json','application/json');}
async function restoreBackup(event){const file=event.target.files?.[0];if(!file)return;try{if(file.size>10000000)throw 0;const backup=JSON.parse(await file.text());if(state.sessions.length&&backup.learner?.name&&state.name&&backup.learner.name!==state.name){toast(L('This backup names another learner. It was not merged.','备份属于另一个学习者，未合并，避免混淆记录。'));return;}const sessions=mergeBackup(state.sessions,backup,C());state.sessions=sessions;if(!state.name&&typeof backup.learner?.name==='string')state.name=backup.learner.name.slice(0,60);if(backup.legacy&&typeof backup.legacy==='object')state.legacy={...backup.legacy,...state.legacy};persist();render();toast(W().backupOk);}catch{toast(W().backupError);}}
function showCredits(){const dialog=$('#creditsDialog');dialog.innerHTML=`<div class="dialog-heading"><h2>${L('Sources & adaptations','来源与改编说明')}</h2><button class="secondary" id="closeCredits">${L('Close','关闭')}</button></div><p>${L('Based on Marble Skill Taxonomy v1 by Generative Spark, Inc. (Marble). The learning map preserves 18 Learning to Learn nodes, 22 internal links and 3 mathematics prerequisites.','基于 Generative Spark, Inc.（Marble）的 Marble Skill Taxonomy v1。地图保留18个学会学习节点、22条内部连线和3条数学学科前置关系。')}</p><p>${L('All 18 skills now have a family activity. Four additional activities from the earlier version remain available. Activities, translations, observation forms and report rules are authored or adapted for this site; they are not validated assessments.','18项能力现在都有亲子案例，旧版另外4个活动也保留。案例、翻译、观察表和报告规则由本站编写或改编，不是经过验证的能力测评。')}</p><p>${L('Database: ODbL 1.0. Marble-authored and adapted text: CC BY-SA 4.0. Upstream curriculum standards retain their own terms; their text is not reproduced here.','数据库采用 ODbL 1.0；Marble 编写及本站改编文字采用 CC BY-SA 4.0。上游课程标准仍遵循各自授权，本站不转载其原文。')}</p><p><a href="https://github.com/withmarbleapp/os-taxonomy" target="_blank" rel="noopener">GitHub ↗</a> · <a href="https://github.com/withmarbleapp/os-taxonomy/blob/main/PROVENANCE.md" target="_blank" rel="noopener">Upstream provenance ↗</a></p><p>${W().method}</p><p>${W().design}</p>`;dialog.showModal();$('#closeCredits').addEventListener('click',()=>dialog.close());}
$('#language').addEventListener('change',e=>{saveForm();state.lang=e.target.value==='zh'?'zh':'en';persist();render();});render();
if(document.modelContext?.registerTool){const controller=new AbortController();const specs=[{name:'list_family_activities',title:'List practice cases',description:'List available activities and their source skill IDs; no learner notes are returned.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||Object.keys(input).length)throw new Error('No parameters accepted');return C().map(c=>({id:c.id,title:c.title,skillId:c.skillId}));}},{name:'open_family_activity',title:'Open a practice case',description:'Open a case in the cases section; does not submit a report.',inputSchema:{type:'object',properties:{activityId:{type:'string'}},required:['activityId'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input.activityId!=='string'||Object.keys(input).some(k=>k!=='activityId'))throw new Error('Invalid input');if(!C().some(c=>c.id===input.activityId))throw new Error('Unknown case');page='cases';setCase(input.activityId);return {caseId:selected};}}];for(const tool of specs)try{Promise.resolve(document.modelContext.registerTool(tool,{signal:controller.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',e=>{if(!e.persisted)controller.abort();});}
